import { normalizeAgentTokenUsage } from './agent_usage_math.mjs'

const AGENT_MESSAGE_ROLES = new Set(['assistant', 'user'])
const AGENT_STATUSES = new Set(['cancelled', 'completed', 'failed', 'running', 'waitingForInput'])
const INTERNAL_EVENT_TYPES = new Set(['closed', 'started', 'turnCompleted'])
export const AGENT_CONVERSATION_USAGE_SCHEMA_VERSION = 1

function requiredString(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Malformed agent conversation: missing ${fieldName}`)

    return value
}

function optionalString(value) {
    return typeof value === 'string' && value.length > 0 ? value : null
}

function optionalInteger(value) {
    return Number.isSafeInteger(value) ? value : null
}

function optionalNonNegativeInteger(value) {
    return Number.isSafeInteger(value) && value >= 0 ? value : null
}

function optionalNumber(value) {
    return typeof value === 'number' && Number.isFinite(value) ? value : null
}

function optionalStringArray(value) {
    return Array.isArray(value) && value.every((entry) => typeof entry === 'string') ? [...value] : null
}

function normalizeMessage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (!AGENT_MESSAGE_ROLES.has(value.role)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    if (!id || !timestamp) return null
    const agent = optionalString(value.agent)
    const sequence = optionalInteger(value.sequence)

    return {
        ...(agent ? { agent } : {}),
        content: value.content,
        id,
        kind: 'message',
        role: value.role,
        ...(sequence !== null ? { sequence } : {}),
        timestamp,
    }
}

function normalizeEvent(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    const type = optionalString(value.type)
    if (!id || !timestamp || !type) return null
    const command = optionalString(value.command)
    const deletions = optionalNonNegativeInteger(value.deletions)
    const details = optionalStringArray(value.details)
    const durationMs = optionalNumber(value.durationMs)
    const exitCode = optionalInteger(value.exitCode)
    const insertions = optionalNonNegativeInteger(value.insertions)
    const label = optionalString(value.label)
    const output = value.type !== 'commandExecution' && typeof value.output === 'string' ? value.output : null
    const providerItemId = optionalString(value.providerItemId)
    const sequence = optionalInteger(value.sequence)
    const status = optionalString(value.status)
    const summary = optionalStringArray(value.summary)
    const workingDirectory = optionalString(value.workingDirectory)

    return {
        ...(command ? { command } : {}),
        content: value.content,
        ...(deletions !== null ? { deletions } : {}),
        ...(details ? { details } : {}),
        ...(durationMs !== null ? { durationMs } : {}),
        ...(exitCode !== null ? { exitCode } : {}),
        id,
        ...(insertions !== null ? { insertions } : {}),
        kind: 'event',
        ...(label ? { label } : {}),
        ...(output !== null ? { output } : {}),
        ...(providerItemId ? { providerItemId } : {}),
        ...(sequence !== null ? { sequence } : {}),
        ...(status ? { status } : {}),
        ...(summary ? { summary } : {}),
        timestamp,
        type,
        ...(workingDirectory ? { workingDirectory } : {}),
    }
}

function normalizeProviderSession(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const agent = optionalString(value.agent)
    const conversationId = optionalString(value.conversationId)
    const createdAt = optionalString(value.createdAt)
    const lastUsedAt = optionalString(value.lastUsedAt)
    const synchronizedThroughMessageId = optionalString(value.synchronizedThroughMessageId)
    if (!agent || !conversationId || !createdAt || !lastUsedAt || !synchronizedThroughMessageId) return null

    return { agent, conversationId, createdAt, lastUsedAt, synchronizedThroughMessageId }
}

function normalizeContextWindowUsage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const { capacityTokens, usedTokens } = value
    if (!Number.isSafeInteger(usedTokens) || usedTokens < 0) return null
    if (!Number.isSafeInteger(capacityTokens) || capacityTokens <= 0) return null

    return { capacityTokens, usedTokens }
}

function normalizeTimer(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Malformed agent conversation: invalid timer')
    }
    const { elapsedMs, runningStartedAt } = value
    if (typeof elapsedMs !== 'number' || !Number.isFinite(elapsedMs) || elapsedMs < 0) {
        throw new Error('Malformed agent conversation: invalid timer.elapsedMs')
    }
    if (runningStartedAt !== null
        && (typeof runningStartedAt !== 'string' || Number.isNaN(Date.parse(runningStartedAt)))) {
        throw new Error('Malformed agent conversation: invalid timer.runningStartedAt')
    }

    return { elapsedMs, runningStartedAt }
}

function normalizeArray(value, normalize) {
    if (!Array.isArray(value)) return []

    return value.map(normalize).filter((entry) => entry !== null)
}

function coalesceDiagnosticEntries(entries) {
    const groupedEntries = []
    for (const entry of entries) {
        const previousEntry = groupedEntries.at(-1)
        if (entry.kind === 'event' && entry.type === 'diagnostic'
            && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            groupedEntries[groupedEntries.length - 1] = {
                ...previousEntry,
                content: `${previousEntry.content}\n${entry.content}`,
            }
            continue
        }
        groupedEntries.push(entry)
    }

    return groupedEntries
}

function isConversationEntry(entry) {
    if (entry.kind !== 'event') return true
    if (INTERNAL_EVENT_TYPES.has(entry.type)) return false

    return entry.type !== 'error' || typeof entry.providerItemId === 'string'
}

function normalizeEntries(value) {
    if (!Array.isArray(value)) throw new Error('Malformed agent conversation: missing entries')

    const entries = value.map((entry, index) => {
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
            throw new Error(`Malformed agent conversation: invalid entries[${index}]`)
        }
        const normalized = entry.kind === 'message'
            ? normalizeMessage(entry)
            : entry.kind === 'event'
                ? normalizeEvent(entry)
                : null
        if (!normalized) throw new Error(`Malformed agent conversation: invalid entries[${index}]`)

        return normalized
    })

    return coalesceDiagnosticEntries(entries.filter(isConversationEntry))
}

/** Parse one canonical conversation record and validate every ordered entry. */
export function parseAgentConversation(content, referencePath) {
    const parsed = JSON.parse(content)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Malformed agent conversation: root must be an object')
    const id = requiredString(parsed.id, 'id')
    const status = requiredString(parsed.status, 'status')
    if (!AGENT_STATUSES.has(status)) throw new Error(`Malformed agent conversation: invalid status ${status}`)
    const startedAt = requiredString(parsed.startedAt, 'startedAt')
    const hasExplicitTitle = typeof parsed.title === 'string' && parsed.title.trim().length > 0
    const contextWindowUsage = normalizeContextWindowUsage(parsed.contextWindowUsage)
    const usage = normalizeAgentTokenUsage(parsed.usage)
    if (parsed.usageSchemaVersion !== undefined
        && parsed.usageSchemaVersion !== AGENT_CONVERSATION_USAGE_SCHEMA_VERSION) {
        throw new Error(`Malformed agent conversation: unsupported usageSchemaVersion ${String(parsed.usageSchemaVersion)}`)
    }
    if (usage && parsed.usageSchemaVersion === undefined
        && typeof parsed.usage.totalTokens === 'number'
        && Number.isFinite(parsed.usage.totalTokens)
        && parsed.usage.totalTokens >= 0) {
        usage.totalTokens = parsed.usage.totalTokens
    }
    if (usage && parsed.usageSchemaVersion === AGENT_CONVERSATION_USAGE_SCHEMA_VERSION
        && parsed.usage.totalTokens !== usage.totalTokens) {
        throw new Error('Malformed agent conversation: inconsistent usage.totalTokens')
    }
    const timer = parsed.timer === undefined ? null : normalizeTimer(parsed.timer)
    if (parsed.viewed !== undefined && typeof parsed.viewed !== 'boolean') {
        throw new Error('Malformed agent conversation: invalid viewed')
    }

    return {
        actionId: optionalString(parsed.actionId),
        cardInternalId: optionalString(parsed.cardInternalId),
        cardPath: optionalString(parsed.cardPath),
        completedAt: optionalString(parsed.completedAt),
        ...(contextWindowUsage ? { contextWindowUsage } : {}),
        entries: normalizeEntries(parsed.entries),
        hasExplicitTitle,
        id,
        path: referencePath,
        providerSessions: normalizeArray(parsed.providerSessions, normalizeProviderSession),
        startedAt,
        status,
        ...(timer ? { timer } : {}),
        title: hasExplicitTitle ? parsed.title : id,
        ...(usage ? { usage } : {}),
        ...(parsed.usageSchemaVersion !== undefined ? { usageSchemaVersion: parsed.usageSchemaVersion } : {}),
        viewed: parsed.viewed ?? true,
    }
}

import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { actionPromptDraftService } from '../../../../services/actions/action_prompt_draft_service'
import { actionRunRegistry } from '../../../../services/actions/action_run_registry'
import type {
    ActionRunSettingsStore,
    ResolvedActionRunSettings,
} from '../../../../services/actions/action_run_settings_service'
import { dataService } from '../../../../services/data/data_service'
import { dialogService } from '../../../../services/dialog_service'
import {
    defaultCancelAction,
    defaultCloseWaitingConversation,
    defaultConvertPromptToAction,
    defaultFinishAction,
    defaultRestartAction,
    defaultRunAction,
} from './action_popup_defaults'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import type { ActionRunInputStore } from '../state/action_run_input_store'
import type { ActionRunResultStore } from '../state/action_run_result_store'

const DEFAULT_CONVERT_LABEL_LENGTH = 40

function hasPersistedSubmittedMessage(
    previousConversation: NonNullable<ReturnType<ActionConversationStore['getSnapshot']>['selectedConversation']>,
    currentConversation: ReturnType<ActionConversationStore['getSnapshot']>['selectedConversation'],
    prompt: string,
) {
    if (!currentConversation || currentConversation.path !== previousConversation.path) return false

    const previousEntryIds = new Set(previousConversation.entries.map(({ id }) => id))

    return currentConversation.entries.some((entry) => entry.kind === 'message'
        && entry.role === 'user'
        && entry.content === prompt
        && !previousEntryIds.has(entry.id))
}

function restorePrompt(action: ActionDefinition, context: ActionContext, prompt: string) {
    const currentRun = currentActionRun(action, context)
    actionPromptDraftService.getDraft(action.id, context, currentRun, { prepare: false }).edit(prompt)
}

export interface ActionPopupOperationInput {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    settings: ResolvedActionRunSettings
    settingsStore: ActionRunSettingsStore
}

export function currentActionRun(action: ActionDefinition, context: ActionContext) {
    return actionRunRegistry.getActionRunStore(action.id, context)?.getSnapshot() ?? null
}

export function currentActionPromptDraft(action: ActionDefinition, context: ActionContext, prepare: boolean) {
    const run = currentActionRun(action, context)

    return actionPromptDraftService.getDraft(action.id, context, run, { prepare })
}

async function runWithPrompt(input: ActionPopupOperationInput, prompt: string, previousRunId: string | null = null) {
    const {
        action, context, conversationStore, historyStore, resultStore, runValidationError, settings,
        settingsStore,
    } = input
    resultStore.setRunning()
    try {
        if (runValidationError) throw new Error(runValidationError)

        const liveConversation = currentActionRun(action, context)?.conversation ?? null
        const previousConversation = liveConversation ?? conversationStore.getSnapshot().selectedConversation
        const continuationPath = conversationStore.continuationPath(liveConversation)
        const runInput = action.type === 'agent'
            ? {
                ...(settings.agent ? { agent: settings.agent } : {}),
                ...(continuationPath ? { continueFrom: continuationPath } : {}),
                prompt,
                ...(settings.model ? { model: settings.model } : {}),
                ...(settings.permissionMode ? { permissionMode: settings.permissionMode } : {}),
                thinkingLevel: settings.thinkingLevel,
            }
            : { extraPrompt: prompt }
        const handleStarted = (runId: string) => {
            resultStore.setRunId(runId)
            settingsStore.markSettingsApplied()
            actionPromptDraftService.clearDraft(action.id, context, currentActionRun(action, context))
        }
        const result = previousRunId
            ? await defaultRestartAction(previousRunId, action, context, runInput, handleStarted)
            : await defaultRunAction(action, context, runInput, handleStarted)
        resultStore.setResult(result)
        await historyStore.load()
        if (action.type === 'agent') {
            await conversationStore.load()
            if (previousRunId
                && result.status === 'failed'
                && previousConversation
                && !hasPersistedSubmittedMessage(
                    previousConversation,
                    conversationStore.getSnapshot().selectedConversation,
                    prompt,
                )) {
                restorePrompt(action, context, prompt)
            }
        }
    } catch (error) {
        if (previousRunId) restorePrompt(action, context, prompt)
        const message = error instanceof Error ? error.message : 'Action run failed'
        resultStore.setResult({
            logs: [{
                actionId: action.id,
                actionName: action.label,
                command: null,
                message,
                phase: 'main',
                status: 'failed',
                stderr: message,
                stdout: '',
            }],
            status: 'failed',
        })
        dialogService.error(error, { fallbackMessage: 'Action run failed' })
    }
}

export async function runPopupAction(input: ActionPopupOperationInput) {
    const { action, context, settingsStore } = input
    const run = currentActionRun(action, context)
    const promptDraft = actionPromptDraftService.getDraft(action.id, context, run, { prepare: false })
    const prompt = promptDraft.getSnapshot()
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    const agentActive = sessionActive && run?.activeActionType === 'agent'

    if (agentActive && run) {
        if (run.question || run.approvals.length) return
        if (run.status === 'waitingForInput' && settingsStore.getSnapshot().settingsChangedWhileWaiting) {
            await runWithPrompt(input, prompt, run.runId)
            return
        }
        try {
            if (run.activeActionStreaming) await promptDraft.send()
            else {
                await promptDraft.synchronize()
                actionPromptDraftService.clearDraft(action.id, context, run)
            }
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not send agent message' })
        }
        return
    }

    await runWithPrompt(input, prompt)
}

export async function convertPromptToAction(input: ActionPopupOperationInput) {
    const { action, context, inputStore, settings } = input
    const prompt = currentActionPromptDraft(action, context, false).getSnapshot()
    const { actionLabel } = inputStore.getSnapshot()
    inputStore.setConvertMessage(null)
    try {
        const label = actionLabel.trim().length > 0 ? actionLabel : prompt.trim().slice(0, DEFAULT_CONVERT_LABEL_LENGTH)
        const convertInput = {
            ...(settings.agent ? { agent: settings.agent } : {}),
            context,
            label,
            ...(settings.model ? { model: settings.model } : {}),
            ...(settings.permissionMode ? { permissionMode: settings.permissionMode } : {}),
            prompt,
        }
        const result = await defaultConvertPromptToAction(convertInput)
        inputStore.setConvertMessage(`Saved ${result.path}`)

        return true
    } catch (error) {
        inputStore.setConvertMessage(error instanceof Error ? error.message : 'Could not convert prompt to action')

        return false
    }
}

export async function saveAndRunPopupAction(input: ActionPopupOperationInput) {
    if (!await convertPromptToAction(input)) return

    await runPopupAction(input)
}

async function closeWaitingConversation(
    action: ActionDefinition,
    context: ActionContext,
    conversationStore: ActionConversationStore,
    status: 'cancelled' | 'completed',
) {
    const conversation = conversationStore.getSnapshot().selectedConversation
    if (!conversation) throw new Error('No agent conversation is selected')
    if (conversation.status !== 'waitingForInput') throw new Error('Selected agent conversation is no longer waiting for input')

    const updatedConversation = await defaultCloseWaitingConversation(conversation.path, status)
    conversationStore.updateConversation(updatedConversation)
    dataService.agents.updateAgentConversation(updatedConversation)
    actionPromptDraftService.clearDraft(action.id, context, null)
}

export async function cancelPopupAction(
    action: ActionDefinition,
    context: ActionContext,
    conversationStore: ActionConversationStore,
) {
    const run = currentActionRun(action, context)
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    if (!run || !sessionActive) {
        try {
            await closeWaitingConversation(action, context, conversationStore, 'cancelled')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not stop waiting agent conversation' })
        }
        return
    }

    await defaultCancelAction(run.runId)
    actionPromptDraftService.clearDraft(action.id, context, run)
}

export async function finishPopupAction(
    action: ActionDefinition,
    context: ActionContext,
    conversationStore: ActionConversationStore,
) {
    const run = currentActionRun(action, context)
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    if (!run || !sessionActive) {
        try {
            await closeWaitingConversation(action, context, conversationStore, 'completed')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not finish waiting agent conversation' })
        }
        return
    }

    try {
        await defaultFinishAction(run.runId)
        actionPromptDraftService.clearDraft(action.id, context, run)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Could not finish agent session' })
    }
}

